const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '解一元一次方程' },
      { kind: 'text', payload: '原方程：7x+-3=1x+4' },
      { kind: 'text', payload: '移项' },
      { kind: 'text', payload: '7x − 1x = 4 + 3' },
      { kind: 'text', payload: '合并同类项' },
      { kind: 'text', payload: '6x = 7' },
      { kind: 'text', payload: '系数化为 1' },
      { kind: 'text', payload: 'x = 7/6' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '3' }
    ];
  },
  render: function (input, metrics) {
    var w = input.viewport.widthDu;
    var h = input.viewport.heightDu;
    var gap = Math.min(34, h * 0.05);
    var cardH = Math.min(110, (h - 160 - 2 * gap) / 3);
    if (cardH < 64) cardH = 64;
    var startY = 130;
    var cardW = Math.min(w - 80, 760);
    if (cardW < 240) cardW = w - 40;
    var cardX = (w - cardW) / 2;
    var cards = [
      { x: cardX, y: startY, w: cardW, h: cardH },
      { x: cardX, y: startY + cardH + gap, w: cardW, h: cardH },
      { x: cardX, y: startY + 2 * (cardH + gap), w: cardW, h: cardH }
    ];
    function rr(x, y, ww, hh, r) {
      if (r > ww / 2) r = ww / 2;
      if (r > hh / 2) r = hh / 2;
      return [
        ['M', x + r, y],
        ['L', x + ww - r, y],
        ['Q', x + ww, y, x + ww, y + r],
        ['L', x + ww, y + hh - r],
        ['Q', x + ww, y + hh, x + ww - r, y + hh],
        ['L', x + r, y + hh],
        ['Q', x, y + hh, x, y + hh - r],
        ['L', x, y + r],
        ['Q', x, y, x + r, y],
        ['Z']
      ];
    }
    var paths = [];
    var children = [];
    for (var i = 0; i < cards.length; i++) {
      var c = cards[i];
      var id = 'card' + i;
      paths.push({ id: id, commands: rr(c.x, c.y, c.w, c.h, 16) });
      children.push({ type: 'path', pathId: id, fill: '#F7FAFF' });
      var accentId = 'accent' + i;
      paths.push({ id: accentId, commands: rr(c.x, c.y + 12, 6, c.h - 24, 3) });
      children.push({ type: 'path', pathId: accentId, fill: '#2F6FED' });
      var circleId = 'numCircle' + i;
      var circleX = c.x + Math.min(48, c.w * 0.12);
      var radius = Math.min(22, c.h * 0.22, c.w * 0.08);
      paths.push({ id: circleId, commands: visualSdk.circle(circleX, c.y + c.h / 2, radius) });
      children.push({ type: 'path', pathId: circleId, fill: '#2F6FED' });
    }
    for (var j = 0; j < 2; j++) {
      var y1 = cards[j].y + cards[j].h + 6;
      var y2 = cards[j + 1].y - 6;
      var x = w / 2;
      var lineId = 'conn' + j;
      paths.push({ id: lineId, commands: [['M', x, y1], ['L', x, y2 - 8]] });
      children.push({ type: 'path', pathId: lineId, fill: '#8FB0E8', stroke: { width: 3, cap: 'round' } });
      var headId = 'head' + j;
      paths.push({ id: headId, commands: [['M', x - 7, y2 - 10], ['L', x + 7, y2 - 10], ['L', x, y2], ['Z']] });
      children.push({ type: 'path', pathId: headId, fill: '#8FB0E8' });
    }
    function label(contentId, x, y, hAlign, vAlign, color) {
      return { type: 'label', contentId: contentId, anchor: { x: x, y: y }, hAlign: hAlign, vAlign: vAlign, color: color };
    }
    children.push(label(metrics[0].contentId, w / 2, 44, 'center', 'middle', '#1F2D3D'));
    children.push(label(metrics[1].contentId, w / 2, 88, 'center', 'middle', '#43536B'));
    for (var k = 0; k < 3; k++) {
      var c2 = cards[k];
      var circleX2 = c2.x + Math.min(48, c2.w * 0.12);
      var headingX = c2.x + Math.min(86, c2.w * 0.22);
      children.push(label(metrics[8 + k].contentId, circleX2, c2.y + c2.h / 2, 'center', 'middle', '#FFFFFF'));
      children.push(label(metrics[2 + k * 2].contentId, headingX, c2.y + c2.h * 0.32, 'left', 'middle', '#1F2D3D'));
      children.push(label(metrics[3 + k * 2].contentId, headingX, c2.y + c2.h * 0.70, 'left', 'middle', '#0B4FBE'));
    }
    return {
      schemaVersion: 1,
      sceneId: 'equation-flow-card',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: w, height: h },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
